import{_ as t,C as a,c as i,o as n,al as s,G as r}from"./chunks/framework.B49hNbyQ.js";const v=JSON.parse('{"title":"Observations of the demo","description":"","frontmatter":{},"headers":[],"relativePath":"introduction/hypermedia-in-action/observations-of-the-demo.md","filePath":"introduction/hypermedia-in-action/observations-of-the-demo.md"}'),l={name:"introduction/hypermedia-in-action/observations-of-the-demo.md"};function c(d,e,h,p,m,f){const o=a("comments-section");return n(),i("div",null,[e[0]||(e[0]=s('<h1 id="observations-of-the-demo" tabindex="-1">Observations of the demo <a class="header-anchor" href="#observations-of-the-demo" aria-label="Permalink to &quot;Observations of the demo&quot;">​</a></h1><p>The de-coupling power of the hypermedia approach is clear:</p><ul><li>When both client and backend follow the hypermedia approach, the backend architecture can change without also having to release a new version of the client.</li><li><code>bob</code> is a console application. What if we also had a web application as a client, a mobile app, some B2B integrations? <ul><li>We would have to roll out new versions of each of these clients.</li><li>To avoid such expensive client rollouts, teams will often run multiple versions of the APIs so old clients can use keep using v1 and newer clients can use v2.</li><li>Some teams even include <code>v1</code> in the initial release, anticipating there will be a <code>v2</code></li></ul></li><li>By following the hypermedia approach APIs can evolve without versioning.</li></ul>',3)),r(o,{repo:"pointw-dev/hypermedia-docs",repoId:"R_kgDOODT1fw",category:"General",categoryId:"DIC_kwDOODT1f84CoFLx"})])}const _=t(l,[["render",c]]);export{v as __pageData,_ as default};
